insert into public.sq_lorekeeper (term_id, is_active, grade_level, passage, question, choice_a, choice_b, choice_c, choice_d, correct_choice) values
  (1, true, 4, NULL, 'Which of these best describes what happens to the mass of ice as it melts into water?', 'The mass stays the same; only the state changes', 'The mass disappears completely', 'The mass doubles', 'The mass turns into a gas', 'a'),
  (1, true, 4, NULL, 'Which of these best describes a heterogeneous mixture like a salad?', 'You can see and pick apart the individual ingredients', 'It is completely see-through', 'It has only one ingredient', 'It cannot be separated at all', 'a'),
  (1, true, 4, NULL, 'Which of these forces would act on a ball rolling down a hill?', 'Gravity and friction', 'Only magnetism', 'No forces at all', 'Only sound energy', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why ice skates have thin blades?', 'To reduce friction and glide smoothly across the ice', 'To increase friction and stop movement', 'To make the skater heavier', 'To attract the ice magnetically', 'a'),
  (1, true, 4, NULL, 'A moving car has what kind of energy due to its motion?', 'Chemical energy only', 'Mechanical energy', 'Light energy', 'Sound energy only', 'b'),
  (1, true, 4, NULL, 'Which of these best explains why metal pots often have plastic or wooden handles?', 'Metal conducts heat well, so an insulating handle prevents burns', 'Plastic conducts heat better than metal', 'Wooden handles make the pot heavier', 'It has no practical reason', 'a'),
  (1, true, 4, NULL, 'When you look at yourself in a mirror, which property of light allows this to happen?', 'Absorption', 'Reflection', 'Refraction only', 'Radiation only', 'b'),
  (1, true, 4, NULL, 'A straw appearing bent when placed in a glass of water is caused by', 'Reflection', 'Refraction', 'Absorption', 'Conduction', 'b'),
  (1, true, 4, NULL, 'Which of these best explains why a whisper is harder to hear from far away than a shout?', 'A whisper has a lower volume, so its sound waves are weaker over distance', 'Whispers travel faster than shouts', 'Shouts have no sound waves', 'Volume has no effect on how far sound travels', 'a'),
  (1, true, 4, NULL, 'In a garden ecosystem, ladybugs eat aphids that feed on plant leaves. What role do the ladybugs play?', 'Producer', 'Primary consumer', 'Secondary consumer', 'Decomposer', 'c'),
  (1, true, 4, NULL, 'Which of these best explains why decomposers are important even though they don''t hunt or gather food like other consumers?', 'They recycle nutrients from dead organisms back into the soil for producers to use', 'They have no important role at all', 'They only eat living plants', 'They replace the need for producers', 'a'),
  (1, true, 4, NULL, 'A polar bear''s white fur is an adaptation that helps it', 'Blend into snowy surroundings while hunting', 'Swim faster in warm water', 'Fly over long distances', 'Dig burrows underground', 'a'),
  (1, true, 4, NULL, 'Which of these Philippine pre-colonial settlements is believed to have had contact with early Chinese traders based on artifacts found?', 'Coastal barangays that engaged in maritime trade', 'Only inland mountain villages', 'Settlements with no trade at all', 'Settlements found only in modern times', 'a'),
  (1, true, 4, NULL, 'Which of these best describes the historical value of studying pre-colonial Philippine civilizations?', 'It helps Filipinos understand their heritage and identity before foreign influence', 'It has no value for understanding Philippine history', 'It only matters for tourists', 'It replaces the need to study any other era', 'a'),
  (1, true, 4, NULL, 'Palawan, where the Tabon Caves are located, is part of which island group?', 'Luzon', 'Visayas', 'Mindanao', 'None of the island groups', 'a'),
  (1, true, 4, NULL, 'Which of these bodies of water separates the Philippines from Taiwan to the north?', 'The Bashi Channel', 'The Sulu Sea', 'The Celebes Sea', 'The Bay of Bengal', 'a'),
  (1, true, 4, NULL, 'Mount Apo, the highest mountain in the Philippines, is located in', 'Luzon', 'Visayas', 'Mindanao', 'Palawan', 'c'),
  (1, true, 4, NULL, 'Which of these best explains why many Philippine cities are located along coastlines?', 'Coastal areas provide easy access to trade, fishing, and transportation by sea', 'Coastal areas have no natural resources', 'Coastal areas are always in the mountains', 'Cities avoid coastlines entirely', 'a'),
  (1, true, 4, NULL, 'The capital of Brunei, an ASEAN member country, is', 'Bandar Seri Begawan', 'Manila', 'Jakarta', 'Hanoi', 'a'),
  (1, true, 4, NULL, 'The capital of Myanmar, an ASEAN member country, is', 'Naypyidaw', 'Bangkok', 'Hanoi', 'Manila', 'a'),
  (1, true, 4, NULL, 'Which of these is a shared economic benefit for ASEAN member countries?', 'Reduced trade barriers that make buying and selling goods easier between members', 'Higher taxes on all imported goods', 'A ban on trade between members', 'No cooperation on economic matters', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why ASEAN countries hold regular summits and meetings?', 'To discuss regional issues and coordinate policies together', 'To avoid any communication between countries', 'To declare war on non-member countries', 'To end all diplomatic relationships', 'a'),
  (1, true, 4, NULL, 'Iron ore and nickel mined in the Philippines are examples of what type of resource?', 'Mineral resources', 'Agricultural resources', 'Marine resources', 'Forest resources', 'a'),
  (1, true, 4, NULL, 'Mangroves along the coastline are an example of what type of natural resource that also protects against storms?', 'Forest resources', 'Mineral resources', 'Agricultural resources only', 'None of these', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why sustainable use of natural resources matters for future generations?', 'It ensures resources like forests and fish are not completely used up, leaving some for the future', 'It has no effect on future generations', 'It only benefits the current generation', 'It means using as many resources as possible right now', 'a'),
  (1, true, 4, NULL, 'Which of these is an example of manufacturing using a Philippine agricultural resource?', 'Turning coconuts into coconut oil and other coconut products', 'Catching tuna in the ocean', 'Mining for gold', 'Growing rice in a field', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why trade and commerce are important for a country''s economy?', 'They allow countries to exchange goods they have plenty of for goods they need', 'They have no real economic benefit', 'They only benefit foreign countries', 'They prevent any economic growth', 'a'),
  (1, true, 4, NULL, 'A folk tale explaining why the sky is high above the earth is what text type?', 'Narrative', 'Expository only', 'Persuasive only', 'A dictionary entry', 'a'),
  (1, true, 4, NULL, 'An essay describing the parts of a plant cell using scientific facts is what text type?', 'Narrative', 'Descriptive', 'Expository', 'Persuasive', 'c'),
  (1, true, 4, NULL, 'A vivid paragraph describing the colors and smells of a busy market is what text type?', 'Descriptive', 'Expository', 'Persuasive', 'Narrative only', 'a'),
  (1, true, 4, 'Every time Carlo finishes his chores early, his mother gives him extra time to play video games. Today, Carlo finished cleaning his room in record time and immediately asked his mother if he could play.', 'Based on the passage, what can you infer about why Carlo finished his chores quickly?', 'He wanted extra time to play video games', 'He dislikes video games', 'He was forced to clean by his teacher', 'He never finishes chores', 'a'),
  (1, true, 4, NULL, 'Which of these best describes the purpose of a persuasive text?', 'To convince the reader to agree with an opinion or take an action', 'To tell a made-up story', 'To give step-by-step instructions only', 'To list facts with no argument', 'a'),
  (1, true, 4, NULL, 'Which of these sentences states a FACT rather than an opinion?', 'The Philippines gained independence in 1898.', 'History class is the most boring subject.', 'Everyone should study history.', 'The past is not important.', 'a'),
  (1, true, 4, NULL, 'In the sentence "The computer screen glared angrily at me," which figure of speech is used?', 'Personification', 'Simile', 'Hyperbole', 'Onomatopoeia', 'a'),
  (1, true, 4, NULL, 'In the sentence "Her voice was as smooth as silk," which figure of speech is used?', 'Metaphor', 'Simile', 'Personification', 'Hyperbole', 'b'),
  (1, true, 4, NULL, 'In the sentence "The city was an oven in the summer heat," which figure of speech is used?', 'Simile', 'Metaphor', 'Onomatopoeia', 'Personification', 'b'),
  (1, true, 4, NULL, 'In the sentence "I asked her a thousand questions," which figure of speech is used?', 'Hyperbole', 'Simile', 'Metaphor', 'Onomatopoeia', 'a'),
  (1, true, 4, NULL, 'In the sentence "The balloon popped with a bang," which figure of speech is used?', 'Onomatopoeia', 'Simile', 'Personification', 'Metaphor', 'a'),
  (1, true, 4, NULL, 'Which sentence correctly uses a subordinate clause to show cause and effect?', 'Because the road was flooded, traffic slowed down.', 'Because the road, was flooded traffic slowed down.', 'The road was flooded, because traffic, slowed down.', 'Traffic because slowed down the road was flooded.', 'a'),
  (1, true, 4, NULL, 'Which sentence correctly uses the relative pronoun "that"?', 'The cake that she baked was delicious.', 'The cake who she baked was delicious.', 'The cake whom she baked was delicious.', 'The cake whose she baked was delicious.', 'a'),
  (1, true, 4, NULL, 'Which sentence correctly uses the future perfect tense?', 'By next year, she will have graduated.', 'By next year, she has graduated.', 'By next year, she graduate.', 'By next year, she graduating.', 'a'),
  (1, true, 4, NULL, 'Which of these sentences is written in the active voice?', 'The song was sung by the choir.', 'The choir sang the song.', 'The song was performed.', 'It was sung beautifully.', 'b'),
  (1, true, 4, NULL, 'The root word in "disagreement" is', 'dis', 'agree', 'ment', 'disagree', 'b'),
  (1, true, 4, NULL, 'The prefix "pre-" in the word "prehistoric" means', 'After history', 'Before history', 'During history', 'Without history', 'b'),
  (1, true, 4, NULL, 'Which word has a more positive connotation than "nosy"?', 'Curious', 'Snooping', 'Prying', 'Meddling', 'a'),
  (1, true, 4, NULL, 'Which word is a synonym for "delighted"?', 'Miserable', 'Thrilled', 'Bored', 'Angry', 'b'),
  (1, true, 4, NULL, 'Which word is an antonym for "cautious"?', 'Careful', 'Reckless', 'Watchful', 'Wary', 'b'),
  (1, true, 4, NULL, 'Ang isang tekstong naglalarawan ng damdamin at karanasan ng manunulat, karaniwang nasa unang panauhan, ay maituturing na', 'Talaarawan o personal na sanaysay', 'Isang aklat-aralin sa matematika', 'Isang listahan lamang', 'Isang bugtong', 'a'),
  (1, true, 4, NULL, 'Sa pangungusap na "Yumakap ang bundok sa mga ulap," anong tayutay ang ginamit?', 'Simili', 'Personipikasyon', 'Pagmamalabis', 'Onomatopeya', 'b'),
  (1, true, 4, NULL, 'Sa pangungusap na "Kasing lambot ng bulak ang unan," anong tayutay ang ginamit?', 'Simili', 'Metapora', 'Personipikasyon', 'Onomatopeya', 'a'),
  (1, true, 4, NULL, 'Ang salitang "tik-tak" na tumutukoy sa tunog ng orasan ay halimbawa ng anong tayutay?', 'Simili', 'Metapora', 'Onomatopeya', 'Personipikasyon', 'c'),
  (1, true, 4, NULL, 'Ang epiko ay mahalaga sa kultura ng isang bayan dahil', 'Naglalaman ito ng kasaysayan, paniniwala, at pagpapahalaga ng mga ninuno', 'Wala itong kabuluhan sa kasaysayan', 'Isa lamang itong uri ng balita', 'Ginagamit lamang sa matematika', 'a'),
  (1, true, 4, NULL, 'Alin sa mga sumusunod ang pangngalang pambalana?', 'Rizal', 'Maynila', 'Guro', 'Pilipinas', 'c'),
  (1, true, 4, NULL, 'Sa pangungusap na "Marahang humihip ang hangin," alin ang pang-abay?', 'Hangin', 'Humihip', 'Marahang', 'Ang', 'c'),
  (1, true, 4, NULL, 'Ang tatlong pangunahing bahagi ng isang talata ay ang paksang pangungusap, mga detalyeng sumusuporta, at', 'Pangwakas na pangungusap', 'Bantas', 'Larawan', 'Pamagat lamang', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why the Philippines'' many islands historically made travel and communication between communities difficult?', 'Water separated communities, requiring boats and sea travel to connect them', 'The islands were all connected by roads', 'There was no water separating the islands', 'Communities never needed to travel', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why manufacturing adds more value to raw materials than simply selling them unprocessed?', 'Turning raw materials into finished products usually increases their market value', 'Manufacturing decreases the value of materials', 'Raw materials are always worth more unprocessed', 'There is no difference in value', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why authors choose between narrative, descriptive, expository, and persuasive text types?', 'Different purposes call for different structures and styles of writing', 'All text types are exactly the same', 'The choice of text type never matters', 'Only expository text is ever used', 'a'),
  (1, true, 4, NULL, 'Which of these best explains the relationship between light, sound, and how we experience the world through our senses?', 'Light lets us see and sound lets us hear, both relying on waves reaching our sense organs', 'Light and sound have no connection to our senses', 'Only sound is detected by our eyes', 'Only light is detected by our ears', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why studying ASEAN is useful for Filipino students?', 'It helps them understand the Philippines'' role and relationships within the Southeast Asian region', 'It has no relevance to the Philippines', 'ASEAN only affects countries outside Asia', 'It replaces the need to study Philippine history', 'a'),
  (1, true, 4, NULL, 'Bakit mahalagang matutunan ang tamang paggamit ng pangngalan, pandiwa, pang-uri, at pang-abay?', 'Upang maiparating nang malinaw at wasto ang kaisipan sa pagsulat at pagsasalita', 'Wala itong silbi sa pang-araw-araw na komunikasyon', 'Ginagamit lamang ito sa pagsusulit', 'Hindi na kailangan pag-aralan ito', 'a'),
  (1, true, 4, NULL, 'Which of these best explains why the Philippines maintains close cultural ties with other Southeast Asian nations despite being an archipelago?', 'Shared history, trade routes, and geography have connected these cultures for centuries', 'The Philippines has no cultural connection to Southeast Asia', 'Being an archipelago prevents any cultural exchange', 'ASEAN membership erases all cultural ties', 'a');